CREATE TABLE payload_profile_revisions (
 id uuid PRIMARY KEY,profile_id text NOT NULL,version text NOT NULL,config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(profile_id,version)
);
CREATE FUNCTION immutable_payload_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Payload profile revisions are immutable'; END $$;
CREATE TRIGGER payload_revision_immutable BEFORE UPDATE OR DELETE ON payload_profile_revisions FOR EACH ROW EXECUTE FUNCTION immutable_payload_revision();
ALTER TABLE sites ADD COLUMN external_site_id text UNIQUE CHECK(external_site_id ~ '^[A-Za-z0-9_-]{1,128}$');
ALTER TABLE gateways ADD COLUMN external_gateway_id text CHECK(external_gateway_id ~ '^[A-Za-z0-9_-]{1,128}$');
ALTER TABLE gateways ADD CONSTRAINT gateways_external_pair UNIQUE(site_id,external_gateway_id);
ALTER TABLE devices ADD COLUMN external_device_id text CHECK(external_device_id ~ '^[A-Za-z0-9_-]{1,128}$');
ALTER TABLE devices ADD COLUMN payload_profile_revision_id uuid REFERENCES payload_profile_revisions(id);
ALTER TABLE devices ADD CONSTRAINT devices_payload_identity CHECK(payload_profile_revision_id IS NULL OR external_device_id IS NOT NULL);
ALTER TABLE devices ADD CONSTRAINT devices_external_pair UNIQUE(gateway_id,external_device_id);
ALTER TABLE gateways DROP CONSTRAINT gateways_topic_matches_name;
ALTER TABLE gateways ADD CONSTRAINT gateways_topic_matches_name CHECK(name !~ '[/+#]' AND lower(name) NOT IN ('response','config','ack') AND (endpoint IN ('energy/'||name||'/#','/'||name||'/#') OR (external_gateway_id IS NOT NULL AND endpoint ~ '^solar/v1/sites/[A-Za-z0-9_-]{1,128}/gateways/[A-Za-z0-9_-]{1,128}/devices/\+/telemetry$')));
CREATE FUNCTION validate_payload_gateway_topic() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.endpoint LIKE 'solar/v1/%' AND NEW.endpoint IS DISTINCT FROM ('solar/v1/sites/'||(SELECT external_site_id FROM sites WHERE id=NEW.site_id)||'/gateways/'||NEW.external_gateway_id||'/devices/+/telemetry') THEN RAISE EXCEPTION 'Payload topic does not match registered site/gateway'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payload_gateway_topic BEFORE INSERT OR UPDATE ON gateways FOR EACH ROW EXECUTE FUNCTION validate_payload_gateway_topic();
CREATE TABLE payload_messages (
 id uuid PRIMARY KEY,gateway_id uuid NOT NULL REFERENCES gateways(id) ON DELETE CASCADE,device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,message_id text NOT NULL,digest text NOT NULL,accepted_at timestamptz NOT NULL,profile_revision_id uuid NOT NULL REFERENCES payload_profile_revisions(id),lot_number bigint NOT NULL CHECK(lot_number BETWEEN 1 AND 4294967295),sequence bigint NOT NULL,polled_at timestamptz NOT NULL,sent_at timestamptz NOT NULL,raw_payload jsonb NOT NULL,unmapped jsonb NOT NULL,UNIQUE(gateway_id,device_id,message_id)
);
CREATE TABLE payload_samples (
 id uuid PRIMARY KEY,message_id uuid NOT NULL REFERENCES payload_messages(id) ON DELETE CASCADE,site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE,gateway_id uuid NOT NULL REFERENCES gateways(id) ON DELETE CASCADE,device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,profile_revision_id uuid NOT NULL REFERENCES payload_profile_revisions(id),tag text NOT NULL,value double precision NOT NULL,unit text NOT NULL,raw_value double precision NOT NULL,raw_unit text NOT NULL,poll_group text NOT NULL,polled_at timestamptz NOT NULL,measured_at timestamptz,received_at timestamptz NOT NULL,quality text NOT NULL,communication text NOT NULL
);
CREATE INDEX payload_samples_latest ON payload_samples(site_id,device_id,tag,polled_at DESC,received_at DESC);
CREATE TABLE payload_rejections (id uuid PRIMARY KEY,site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE,gateway_id uuid NOT NULL REFERENCES gateways(id) ON DELETE CASCADE,topic text NOT NULL,reason text NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX payload_rejections_recent ON payload_rejections(gateway_id,received_at DESC);
ALTER TABLE telemetry_raw ADD COLUMN payload_profile_revision_id uuid REFERENCES payload_profile_revisions(id);
