INSERT INTO payload_profile_revisions(id,profile_id,version,config) VALUES ('00000000-0000-4000-8000-000000000002','huawei-smartlogger3000a','1.0.0','{"id":"huawei-smartlogger3000a","version":"1.0.0","schemaVersion":"1.1","displayName":"Huawei SmartLogger3000A","deviceType":"solar-logger","pollGroups":["plant","environment"],"fields":[{"tag":"solar.active_power","displayName":"solar.active_power","pollGroup":"plant","sourceUnit":"W","targetUnit":"W","conversion":"identity","role":"active-power"},{"tag":"solar.reactive_power","displayName":"solar.reactive_power","pollGroup":"plant","sourceUnit":"var","targetUnit":"var","conversion":"identity"},{"tag":"solar.daily_yield","displayName":"solar.daily_yield","pollGroup":"plant","sourceUnit":"Wh","targetUnit":"kWh","conversion":"wh-to-kwh"},{"tag":"solar.total_yield","displayName":"solar.total_yield","pollGroup":"plant","sourceUnit":"Wh","targetUnit":"kWh","conversion":"wh-to-kwh"},{"tag":"environment.irradiance","displayName":"environment.irradiance","pollGroup":"environment","sourceUnit":"W/m2","targetUnit":"W/m2","conversion":"identity"},{"tag":"environment.ambient_temperature","displayName":"environment.ambient_temperature","pollGroup":"environment","sourceUnit":"degC","targetUnit":"degC","conversion":"identity"},{"tag":"environment.module_temperature","displayName":"environment.module_temperature","pollGroup":"environment","sourceUnit":"degC","targetUnit":"degC","conversion":"identity"},{"tag":"environment.wind_speed","displayName":"environment.wind_speed","pollGroup":"environment","sourceUnit":"m/s","targetUnit":"m/s","conversion":"identity"}]}'::jsonb);
